import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"4.3 View, approve, and take over on the phone","description":"Keep only key actions and short-lived authority on the phone, revocable if lost.","frontmatter":{"title":"4.3 View, approve, and take over on the phone","description":"Keep only key actions and short-lived authority on the phone, revocable if lost.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4/4-3.md","filePath":"en/delivery/stage-4/4-3.md","lastUpdated":1794015952000}'),n={name:"en/delivery/stage-4/4-3.md"};function i(s,e,l,h,p,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-3-view-approve-and-take-over-on-the-phone" tabindex="-1">4.3 View, approve, and take over on the phone <a class="header-anchor" href="#_4-3-view-approve-and-take-over-on-the-phone" aria-label="Permalink to &quot;4.3 View, approve, and take over on the phone&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Not implemented:</strong> No mobile PWA, phone pairing, push, mobile approval, or remote takeover.</li><li><strong>Current entry:</strong> Only the same-machine web control surface. This step is a prerequisite for accepting Phase 4 as a whole.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let the user view, approve, and take over from a phone, while ensuring a lost phone can be revoked immediately and long-term primary authority is not stored on it.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Provide a phone web entry for today&#39;s tasks, items that need the user, and artifacts.</li><li>The approval page shows the real target, content, impact, and whether it can be undone; key actions require a second confirmation.</li><li>Support pause, takeover, and stop from the phone; takeover stops automatic operation immediately.</li><li>Pair with a short-lived code; the phone does not store long-term primary authority, and push content does not include sensitive text.</li><li>A lost phone can be revoked immediately; after revocation it cannot approve, take over, or view tasks.</li><li>When offline, offer read-only access and a clear state, then sync after reconnecting.</li></ol>',7)])])}const v=t(n,[["render",i]]);export{u as __pageData,v as default};
